  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import {
  9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
 10→  FileText, Archive
 11→} from "lucide-react";
 12→import { toast } from "sonner";
 13→import type { Result } from "@/pages/Index";
 14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 15→// Sub-components
 16→import CandidateSummary from "@/components/candidate/CandidateSummary";
 17→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 18→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 19→import EducationPanel from "@/components/candidate/EducationPanel";
 20→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 21→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 22→import AINudgePanel from "@/components/candidate/AINudgePanel";
 23→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 24→import StageTracker from "@/components/candidate/StageTracker";
 25→import type { HiringStage } from "@/hooks/useStageTracker";
 26→
 27→interface CandidateRowProps {
 28→  result: Result;
 29→  index: number;
 30→  isExpanded: boolean;
 31→  isSelected: boolean;
 32→  jobTitle?: string | null;
 33→  onToggleRow: (id: string) => void;
 34→  onToggleSelect: (resumeId: string) => void;
 35→  onDownload: (filePath: string, filename: string) => void;
 36→  onDelete: (resumeId: string, filePath: string | null) => void;
 37→  onDismiss: (resumeId: string) => void;
 38→  formatCandidateName: (filename: string) => string;
 39→  currentStage?: HiringStage | null;
 40→  stageUpdatedAt?: string | null;
 41→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 42→  onRewriteJd?: () => void;
 43→}
 44→
 45→const getScoreColor = (score: number) => {
 46→  if (score >= 70) return "bg-score-skills";
 47→  if (score >= 40) return "bg-warning";
 48→  return "bg-destructive";
 49→};
 50→
 51→const getScoreTextColor = (score: number) => {
 52→  if (score >= 70) return "text-score-skills";
 53→  if (score >= 40) return "text-warning";
 54→  return "text-destructive";
 55→};
 56→
 57→const STAGE_BADGE_CLASSES: Record<string, string> = {
 58→  applied: "border-border bg-muted/50 text-muted-foreground",
 59→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 60→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 61→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 62→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 63→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 64→};
 65→
 66→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 67→  if (score >= 70) return { label: "Strong", variant: "success" };
 68→  if (score >= 40) return { label: "Good", variant: "warning" };
 69→  return { label: "Weak", variant: "destructive" };
 70→};
 71→
 72→const getRankDisplay = (index: number) => {
 73→  if (index < 3) {
 74→    const colors = [
 75→      "bg-score-overall text-white",
 76→      "bg-muted-foreground/60 text-white",
 77→      "bg-warning text-white",
 78→    ];
 79→    return (
 80→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 81→        {index + 1}
 82→      </span>
 83→    );
 84→  }
 85→  return (
 86→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 87→      {index + 1}
 88→    </span>
 89→  );
 90→};
 91→
 92→const CandidateRow = ({
 93→  result: r,
 94→  index,
 95→  isExpanded,
 96→  isSelected,
 97→  jobTitle,
 98→  onToggleRow,
 99→  onToggleSelect,
100→  onDownload,
101→  onDelete,
102→  onDismiss,
103→  formatCandidateName,
104→  currentStage,
105→  stageUpdatedAt,
106→  onStageChange,
107→  onRewriteJd,
108→}: CandidateRowProps) => {
109→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
110→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
111→
112→  return (
113→    <>
114→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
115→      <>
116→        {/* Collapsed Row */}
117→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
118→          <TableCell onClick={(e) => e.stopPropagation()}>
119→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
120→          </TableCell>
121→          <TableCell className="text-center">
122→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
123→          </TableCell>
124→          <TableCell className="font-medium">
125→            <div className="flex flex-col gap-0.5">
126→              <div className="flex items-center gap-1.5 flex-wrap">
127→                <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
128→                {!r.pending && currentStage && currentStage !== "applied" && (
129→                  <Badge
130→                    variant="outline"
131→                    className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
132→                  >
133→                    {currentStage}
134→                  </Badge>
135→                )}
136→              </div>
137→              {r.candidate_location && (
138→                <span className="flex items-center gap-1 text-xs text-muted-foreground">
139→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
140→                </span>
141→              )}
142→            </div>
143→          </TableCell>
144→          <TableCell>
145→            {r.pending ? (
146→              <Badge variant="outline" className="text-xs">Pending</Badge>
147→            ) : (
148→              <div className="flex items-center gap-2">
149→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
150→                  <div
151→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
152→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
153→                  />
154→                </div>
155→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
156→                  {r.overall_score?.toFixed(0)}%
157→                </span>
158→              </div>
159→            )}
160→          </TableCell>
161→          <TableCell>
162→            <div className="flex flex-wrap items-center gap-1">
163→              {!r.pending && strength && (
164→                <Badge variant={strength.variant} className="text-[10px]">
165→                  {strength.label}
166→                </Badge>
167→              )}
168→              {!r.pending && r.scoring_version === "heuristic" && (
169→                <TooltipProvider delayDuration={300}>
170→                  <Tooltip>
171→                    <TooltipTrigger asChild>
172→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
173→                        Quick
174→                      </span>
175→                    </TooltipTrigger>
176→                    <TooltipContent className="max-w-xs text-xs">
177→                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
178→                    </TooltipContent>
179→                  </Tooltip>
180→                </TooltipProvider>
181→              )}
182→            </div>
183→          </TableCell>
184→          <TableCell>
185→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
186→              <TooltipProvider delayDuration={300}>
187→                {/* Phone */}
188→                <Tooltip>
189→                  <TooltipTrigger asChild>
190→                    {r.candidate_phone ? (
191→                      <a
192→                        href={`tel:${r.candidate_phone}`}
193→                        onClick={(e) => {
194→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
195→                            e.preventDefault();
196→                            navigator.clipboard.writeText(r.candidate_phone!);
197→                            toast.success("Phone number copied!");
198→                          }
199→                        }}
200→                      >
201→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
202→                          <Phone className="h-3.5 w-3.5" />
203→                        </Button>
204→                      </a>
205→                    ) : (
206→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
207→                        <Phone className="h-3.5 w-3.5" />
208→                      </Button>
209→                    )}
210→                  </TooltipTrigger>
211→                  <TooltipContent>{r.candidate_phone ? `Copy: ${r.candidate_phone}` : "Phone not found in resume"}</TooltipContent>
212→                </Tooltip>
213→
214→                {/* Email */}
215→                <Tooltip>
216→                  <TooltipTrigger asChild>
217→                    {r.candidate_email ? (
218→                      <Button
219→                        variant="ghost"
220→                        size="icon"
221→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
222→                        onClick={() => setEmailDialogOpen(true)}
223→                      >
224→                        <Mail className="h-3.5 w-3.5" />
225→                      </Button>
226→                    ) : (
227→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
228→                        <Mail className="h-3.5 w-3.5" />
229→                      </Button>
230→                    )}
231→                  </TooltipTrigger>
232→                  <TooltipContent>{r.candidate_email ? `Email: ${r.candidate_email}` : "Email not found in resume"}</TooltipContent>
233→                </Tooltip>
234→
235→                {/* Download */}
236→                <Tooltip>
237→                  <TooltipTrigger asChild>
238→                    {r.file_path ? (
239→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
240→                        <FileText className="h-3.5 w-3.5" />
241→                      </Button>
242→                    ) : (
243→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
244→                        <FileText className="h-3.5 w-3.5" />
245→                      </Button>
246→                    )}
247→                  </TooltipTrigger>
248→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
249→                </Tooltip>
250→
251→                {/* Archive */}
252→                <Tooltip>
253→                  <TooltipTrigger asChild>
254→                    <Button
255→                      variant="ghost" size="icon"
256→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
257→                      onClick={() => onDismiss(r.resume_id)}
258→                    >
259→                      <Archive className="h-3.5 w-3.5" />
260→                    </Button>
261→                  </TooltipTrigger>
262→                  <TooltipContent>Archive candidate</TooltipContent>
263→                </Tooltip>
264→              </TooltipProvider>
265→
266→              {!r.pending && (
267→                <CollapsibleTrigger asChild>
268→                  <Button variant="ghost" size="icon" className="h-7 w-7">
269→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
270→                  </Button>
271→                </CollapsibleTrigger>
272→              )}
273→            </div>
274→          </TableCell>
275→        </TableRow>
276→
277→        {/* Expanded Detail — New Layout */}
278→        {!r.pending && (
279→          <CollapsibleContent asChild>
280→            <TableRow className="bg-muted/30 hover:bg-muted/30">
281→              <TableCell colSpan={6} className="p-5">
282→                <div className="space-y-4">
283→                  {/* 1. Summary + Stage Tracker — unified overview card */}
284→                  {(() => {
285→                    const hasSummary = !!(r.explanation_json?.summary || r.summary);
286→                    if (!hasSummary && !onStageChange) return null;
287→                    return (
288→                      <div className="rounded-lg border bg-background overflow-hidden">
289→                        {hasSummary && (
290→                          <div className="px-4 py-3">
291→                            <CandidateSummary result={r} />
292→                          </div>
293→                        )}
294→                        {onStageChange && (
295→                          <div className={`px-4 py-3${hasSummary ? " border-t bg-muted/40" : ""}`}>
296→                            <StageTracker
297→                              currentStage={currentStage || "applied"}
298→                              updatedAt={stageUpdatedAt}
299→                              onStageChange={(stage) => onStageChange(r.resume_id, stage)}
300→                            />
301→                          </div>
302→                        )}
303→                      </div>
304→                    );
305→                  })()}
306→
307→                  {/* 2. Strengths & Gaps — high signal, show first */}
308→                  <StrengthsGapsPanel result={r} />
309→
310→                  {/* 3. Skills Detail | Experience | Education — 3 columns */}
311→                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
312→                    <SkillsDetailPanel result={r} />
313→                    <ExperiencePanel parsedJson={r.parsed_json} />
314→                    <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
315→                  </div>
316→
317→                  {/* 4. JD Aligned — full width */}
318→                  <JDAlignedPanel result={r} />
319→
320→                  {/* 6. AI Nudge + Rewrite JD */}
321→                  <AINudgePanel result={r} onRewriteJd={onRewriteJd} />
322→
323→                  {/* 7. Interview Questions — collapsible */}
324→                  <InterviewQuestionsPanel result={r} />
325→                </div>
326→              </TableCell>
327→            </TableRow>
328→          </CollapsibleContent>
329→        )}
330→      </>
331→    </Collapsible>
332→
333→    {r.candidate_email && (
334→      <EmailOutreachDialog
335→        open={emailDialogOpen}
336→        onOpenChange={setEmailDialogOpen}
337→        candidateName={r.candidate_name || r.filename}
338→        candidateEmail={r.candidate_email}
339→        jobTitle={jobTitle || "Open Position"}
340→        matchScore={Math.round(r.overall_score ?? 0)}
341→        resumeId={r.resume_id}
342→        jobId={r.id}
343→      />
344→    )}
345→    </>
346→  );
347→};
348→
349→export default CandidateRow;
350→

  1→import { useState } from "react";
  2→import { supabase } from "@/integrations/supabase/client";
  3→import { toast } from "sonner";
  4→import { Button } from "@/components/ui/button";
  5→import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
  6→import { Textarea } from "@/components/ui/textarea";
  7→import { Badge } from "@/components/ui/badge";
  8→import { Progress } from "@/components/ui/progress";
  9→import { Loader2, Sparkles, CheckCircle2, XCircle } from "lucide-react";
 10→import { cn } from "@/lib/utils";
 11→
 12→interface QualityScore {
 13→  overall: number;
 14→  clarity: number;
 15→  keywords: number;
 16→  ats_fit: number;
 17→  inclusivity: number;
 18→}
 19→
 20→interface MissingKeyword {
 21→  keyword: string;
 22→  status: "missing" | "detected";
 23→}
 24→
 25→interface RewriteResult {
 26→  rewritten_jd: string;
 27→  quality_score: QualityScore;
 28→  missing_keywords: MissingKeyword[];
 29→}
 30→
 31→interface JDRewriteDialogProps {
 32→  open: boolean;
 33→  onOpenChange: (open: boolean) => void;
 34→  jobId: string;
 35→  originalJd: string;
 36→  onApply: (newJd: string) => void;
 37→}
 38→
 39→const SCORE_LABELS: { key: keyof Omit<QualityScore, "overall">; label: string }[] = [
 40→  { key: "clarity", label: "Clarity" },
 41→  { key: "keywords", label: "Keywords" },
 42→  { key: "ats_fit", label: "ATS Fit" },
 43→  { key: "inclusivity", label: "Inclusivity" },
 44→];
 45→
 46→function scoreColor(score: number): string {
 47→  if (score >= 75) return "bg-green-500";
 48→  if (score >= 50) return "bg-yellow-500";
 49→  return "bg-red-500";
 50→}
 51→
 52→function scoreTextColor(score: number): string {
 53→  if (score >= 75) return "text-green-600";
 54→  if (score >= 50) return "text-yellow-600";
 55→  return "text-red-600";
 56→}
 57→
 58→const JDRewriteDialog = ({ open, onOpenChange, jobId, originalJd, onApply }: JDRewriteDialogProps) => {
 59→  const [loading, setLoading] = useState(false);
 60→  const [result, setResult] = useState<RewriteResult | null>(null);
 61→  const [editedJd, setEditedJd] = useState("");
 62→
 63→  const handleRewrite = async () => {
 64→    setLoading(true);
 65→    setResult(null);
 66→    try {
 67→      const { data, error } = await supabase.functions.invoke("rewrite-jd", {
 68→        body: { job_id: jobId },
 69→      });
 70→      if (error) throw error;
 71→      if (data?.error) throw new Error(data.error);
 72→      setResult(data as RewriteResult);
 73→      setEditedJd(data.rewritten_jd);
 74→      toast.success("JD rewrite complete");
 75→    } catch (err: any) {
 76→      toast.error(err?.message || "Failed to rewrite JD");
 77→    } finally {
 78→      setLoading(false);
 79→    }
 80→  };
 81→
 82→  const handleApply = () => {
 83→    if (!editedJd.trim()) return;
 84→    onApply(editedJd);
 85→    onOpenChange(false);
 86→    toast.success("Rewritten JD applied");
 87→  };
 88→
 89→  const handleClose = () => {
 90→    if (loading) return;
 91→    onOpenChange(false);
 92→  };
 93→
 94→  const handleOpenChange = (nextOpen: boolean) => {
 95→    if (!nextOpen && loading) return;
 96→    if (!nextOpen) {
 97→      // Reset state when closing
 98→      setResult(null);
 99→      setEditedJd("");
100→    }
101→    onOpenChange(nextOpen);
102→  };
103→
104→  return (
105→    <Dialog open={open} onOpenChange={handleOpenChange}>
106→      <DialogContent className="max-w-5xl w-full max-h-[90vh] overflow-hidden flex flex-col">
107→        <DialogHeader className="shrink-0">
108→          <DialogTitle className="flex items-center gap-2">
109→            <Sparkles className="h-5 w-5 text-primary" />
110→            AI Rewrite JD
111→          </DialogTitle>
112→        </DialogHeader>
113→
114→        <div className="flex-1 overflow-y-auto min-h-0">
115→          {!result && !loading && (
116→            <div className="flex flex-col items-center justify-center py-12 gap-4 text-center">
117→              <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center">
118→                <Sparkles className="h-7 w-7 text-primary" />
119→              </div>
120→              <div>
121→                <p className="font-semibold text-base mb-1">Rewrite for Clarity &amp; ATS Optimization</p>
122→                <p className="text-sm text-muted-foreground max-w-sm">
123→                  AI will rewrite your JD for clarity and inclusivity, score its quality on 4 dimensions, and identify missing keywords.
124→                  Costs 1 credit.
125→                </p>
126→              </div>
127→              <Button onClick={handleRewrite} className="gap-2">
128→                <Sparkles className="h-4 w-4" />
129→                Rewrite JD
130→              </Button>
131→            </div>
132→          )}
133→
134→          {loading && (
135→            <div className="flex flex-col items-center justify-center py-16 gap-3">
136→              <Loader2 className="h-8 w-8 text-primary animate-spin" />
137→              <p className="text-sm text-muted-foreground">Analyzing and rewriting your JD…</p>
138→            </div>
139→          )}
140→
141→          {result && (
142→            <div className="space-y-6 pb-4">
143→              {/* Two-column JD side by side */}
144→              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
145→                <div className="flex flex-col gap-2">
146→                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Original JD</p>
147→                  <Textarea
148→                    readOnly
149→                    value={originalJd}
150→                    className="min-h-[280px] resize-none text-sm bg-muted/40 cursor-default"
151→                  />
152→                </div>
153→                <div className="flex flex-col gap-2">
154→                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
155→                    Rewritten JD
156→                    <span className="ml-2 text-[10px] normal-case font-normal text-muted-foreground">(editable)</span>
157→                  </p>
158→                  <Textarea
159→                    value={editedJd}
160→                    onChange={(e) => setEditedJd(e.target.value)}
161→                    className="min-h-[280px] resize-none text-sm"
162→                  />
163→                </div>
164→              </div>
165→
166→              {/* Quality Score */}
167→              <div className="space-y-3">
168→                <div className="flex items-center justify-between">
169→                  <p className="text-sm font-semibold">Quality Score (Original)</p>
170→                  <span className={cn("text-sm font-bold", scoreTextColor(result.quality_score.overall))}>
171→                    {result.quality_score.overall}/100
172→                  </span>
173→                </div>
174→                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
175→                  {SCORE_LABELS.map(({ key, label }) => {
176→                    const score = result.quality_score[key];
177→                    return (
178→                      <div key={key} className="space-y-1">
179→                        <div className="flex items-center justify-between text-xs">
180→                          <span className="text-muted-foreground">{label}</span>
181→                          <span className={cn("font-medium", scoreTextColor(score))}>{score}</span>
182→                        </div>
183→                        <div className="h-2 rounded-full bg-muted overflow-hidden">
184→                          <div
185→                            className={cn("h-full rounded-full transition-all duration-500", scoreColor(score))}
186→                            style={{ width: `${score}%` }}
187→                          />
188→                        </div>
189→                      </div>
190→                    );
191→                  })}
192→                </div>
193→              </div>
194→
195→              {/* Missing Keywords */}
196→              {result.missing_keywords.length > 0 && (
197→                <div className="space-y-2">
198→                  <p className="text-sm font-semibold">Keyword Analysis</p>
199→                  <div className="flex flex-wrap gap-2">
200→                    {result.missing_keywords.map((kw) => (
201→                      <Badge
202→                        key={kw.keyword}
203→                        variant="outline"
204→                        className={cn(
205→                          "gap-1 text-xs",
206→                          kw.status === "detected"
207→                            ? "border-green-500/50 text-green-700 bg-green-50 dark:text-green-400 dark:bg-green-950/30"
208→                            : "border-red-500/50 text-red-700 bg-red-50 dark:text-red-400 dark:bg-red-950/30"
209→                        )}
210→                      >
211→                        {kw.status === "detected" ? (
