 16→// ── Robust prompt template substitution ─────────────────────
 17→function applyPromptTemplate(template: string, vars: Record<string, string>): string {
 18→  return template.replace(/\$\{(\w+(?:\.\w+)*)\}/g, (match, key) => {
 19→    if (key in vars) return vars[key];
 20→    console.warn(`Prompt template: unresolved variable ${match}`);
 21→    return "None specified";
 22→  });
