658→          const summary = `Ranked by resume similarity (${Math.round(similarity * 100)}%). Matched: ${matchedSkills.slice(0, 5).join(', ') || 'none'}. Missing: ${missingSkills.slice(0, 5).join(', ') || 'none'}.`;
659→          await supabase.from("resumes").update({ status: "done" }).eq("id", resume.id);
660→          const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resume.id).limit(1).single();
661→          const resultData = {
662→            resume_id: resume.id, job_id, scoring_version: "heuristic",
663→            overall_score: overallScore, hard_fit: hardFit,
664→            confidence: totalKeywords > 0 ? Math.min(Math.round((matchedCount / totalKeywords) * 50), 50) : 15,
665→            category_scores_json: {}, strengths_json: matchedSkills.slice(0, 8),
666→            gaps_json: missingSkills.slice(0, 8), interview_questions: [],
667→            explanation_json: { summary }, matched_must_haves: matchedSkills,
668→            missing_must_haves: missingSkills, missing_skills: missingSkills, summary,
669→            skill_score: null, experience_score: null, education_score: null,
670→          };
671→          if (existingResult) await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
672→          else await supabase.from("results").insert(resultData as any);
673→        }
674→      }
675→
676→      await supabase.from("jobs").update({
677→        status: "completed", completed_at: new Date().toISOString(),
678→      }).eq("id", job_id);
679→      console.log(`Job ${job_id} completed`);
680→
681→      // Send notification email (fire-and-forget)
682→      try {
683→        const { data: authUser } = await supabase.auth.admin.getUserById(userId);
684→        const userEmail = authUser?.user?.email;
685→        if (userEmail) {
686→          const jobTitle = job.title || job.job_description?.slice(0, 50) || "Untitled Job";
687→          await supabase.functions.invoke("send-email", {
688→            body: {
689→              to: userEmail, template_key: "ranking_complete",
690→              variables: {
691→                user_name: userEmail.split("@")[0], job_title: jobTitle,
692→                resume_count: String(allTargetIds.length), job_id,
693→                app_url: Deno.env.get("APP_URL") || "https://rankora.co",
694→              },
695→            },
696→          });
697→        }
698→      } catch (emailErr) {
699→        console.error("Failed to send ranking notification email:", emailErr);
700→      }
701→    }
702→
703→    return new Response(JSON.stringify({ success: true, message: "Ranking started", job_id }), {
704→      headers: { ...corsHeaders, "Content-Type": "application/json" },
705→    });
706→  } catch (err) {
707→    console.error("rank-resumes error:", err);
708→    await logSystemError({ function_name: "rank-resumes", error_type: "TOP_LEVEL", severity: "critical", error_message: errorToMessage(err), error_stack: errorToStack(err) });
709→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
710→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
711→    });
712→  }
713→});
